<ul id="items"></ul>
</section>

<script>
const $ = (id) => document.getElementById(id);
let userId = localStorage.getItem('userId');
let userName = localStorage.getItem('userName');
let ws = null;
let wsUrl = null;
const watched = new Set();
const itemEls = new Map();

function msg(t) { $('msg').textContent = t || ''; }
function showMe() { $('me').textContent = userId ? 'Registered as ' + userName : 'Not registered'; }

async function api(method, url, body) {
  const r = await fetch(url, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await r.json();
  if (!r.ok) throw new Error(data.error || r.statusText);
  return data;
}

function describe(v) {
  const it = v.item || v;
  let s = it.title + ' [' + it.status + '] start ' + it.startingPrice + ' ' + it.currency;
  if (it.highestBidAmount !== null) s += ', highest ' + it.highestBidAmount + ' ' + it.currency;
  if (v.displayCurrency) {
    s += ' (' + (v.convertedStartingPrice === null ? 'no rate' : v.convertedStartingPrice.toFixed(2) + ' ' + v.displayCurrency) + ')';
  }
  s += ', ends ' + new Date(it.endTime).toLocaleString();
  if (it.winnerId) s += ', winner ' + it.winnerId;
  return s;
}

async function refreshOne(id) {
  const dc = $('display').value;
  const v = await api('GET', '/api/items/' + encodeURIComponent(id) + (dc ? '?displayCurrency=' + dc : ''));
  const el = itemEls.get(id);
  if (el) el.textContent = describe(v);
}

async function refresh() {
  try {
    msg('');
    const items = await api('GET', '/api/items');
    const ul = $('items');
    ul.textContent = '';
    itemEls.clear();
    for (const it of items) {
      const li = document.createElement('li');
      const span = document.createElement('span');
      const amt = document.createElement('input');
      amt.type = 'number'; amt.step = '0.01'; amt.placeholder = 'Bid';
      const btn = document.createElement('button');
      btn.textContent = 'Bid';
      btn.onclick = async () => {
        try {
          msg('');
          if (!userId) throw new Error('Register first');
          await api('POST', '/api/items/' + encodeURIComponent(it.id) + '/bids', { userId, amount: Number(amt.value) });
          await refreshOne(it.id);
        } catch (e) { msg(e.message); }
      };
      li.append(span, amt, btn);
      ul.appendChild(li);
      itemEls.set(it.id, span);
      watch(it.id);
      refreshOne(it.id).catch((e) => msg(e.message));
    }
  } catch (e) { msg(e.message); }
}

function send(o) { if (ws && ws.readyState === 1) ws.send(JSON.stringify(o)); }
function watch(id) { watched.add(id); send({ action: 'watch', itemId: id }); }

async function connect() {
  try {
    if (!wsUrl) wsUrl = (await api('GET', '/api/config'))['live-update-server'];
    ws = new WebSocket(wsUrl);
    ws.onopen = () => watched.forEach((id) => send({ action: 'watch', itemId: id }));
    ws.onmessage = (e) => {
      try {
        const ev = JSON.parse(e.data);
        if (ev.itemId) refreshOne(ev.itemId).catch(() => {});
      } catch (_) {}
    };
    ws.onclose = () => setTimeout(connect, 2000);
  } catch (e) { setTimeout(connect, 5000); }
}

$('register').onclick = async () => {
  try {
    msg('');
    const u = await api('POST', '/api/users', { displayName: $('name').value });
    userId = u.id; userName = u.displayName;
    localStorage.setItem('userId', userId);
    localStorage.setItem('userName', userName);
    showMe();
  } catch (e) { msg(e.message); }
};
$('list').onclick = async () => {
  try {
    msg('');
    if (!userId) throw new Error('Register first');
    await api('POST', '/api/items', {
      userId,
      title: $('title').value,
      startingPrice: Number($('price').value),
      endTime: new Date($('end').value).toISOString(),
      currency: $('currency').value,
    });
    await refresh();
  } catch (e) { msg(e.message); }
};
$('refresh').onclick = refresh;
$('display').onchange = refresh;

showMe();
refresh();
connect();
</script>
</body>
</html>
